<template><AppShell :title="item?.kind==='REQUEST'?'求购详情':'道具详情'" back footer><StateView :loading="loading" :error="error" :count="item?1:0" @retry="load" /><template v-if="item"><swiper class="detail-swiper" indicator-dots indicator-active-color="#ffe433"><swiper-item v-if="!pictures.length"><GameArt variant="detail" :game="item.game" class="detail-art"><text class="detail-art-title">{{item.game}} · 地铁逃生</text></GameArt></swiper-item><swiper-item v-for="pic in pictures" :key="pic"><image :src="imageUrl(pic)" class="detail-art" mode="aspectFill" @click="preview(pic)" /></swiper-item></swiper><view class="card detail-intro"><view class="row between"><text class="price">¥{{money(item.priceCents)}}<text class="price-unit">{{item.pricingMode==='UNIT'?'/ 件':'/ 整批'}}</text></text><text class="muted tiny">已完成 {{item.sales}} 单</text></view><text class="detail-title">{{item.title}}</text><view class="row assurances"><text v-if="item.kind==='REQUEST'&&item.status==='ACTIVE'" class="tag">✓ 求购已审核</text><text v-else-if="item.shopStatus==='APPROVED'&&item.realnameStatus==='VERIFIED'" class="tag">✓ 认证店铺</text><text class="tag">✓ 游戏内交付</text><text class="tag">✓ 平台售后</text></view></view><view class="pad" style="padding-top:0"><view class="card row" @click="go('shop/index',{id:item.ownerId})"><GameArt avatar :type="item.avatar" :src="item.avatar?.startsWith('/')?item.avatar:''" /><view class="stack flex-1"><text class="bold">{{item.nickname}}</text><text class="muted tiny">{{item.shopStatus==='APPROVED'?'已认证店铺':'未认证店铺'}}</text></view><button class="ui-button btn small">进店<AppIcon class="app-icon" name="chevron" :size="12" /></button></view><view class="card"><text class="field-label">道具介绍</text><view class="spec-grid"><view v-for="spec in specs" :key="spec.label" class="spec-item"><text class="muted tiny">{{spec.label}}</text><text>{{spec.value}}</text></view></view></view><view class="card"><view class="tabs"><button class="ui-button" :class="{selected:tab==='description'}" @click="tab='description'">道具说明</button><button class="ui-button" :class="{selected:tab==='reviews'}" @click="tab='reviews'">用户评价 {{item.reviewTotal??item.reviews.length}}</button></view><view v-if="tab==='description'" class="description"><text v-if="item.description">{{item.description}}</text><image v-for="pic in details" :key="pic" :src="imageUrl(pic)" mode="widthFix" class="detail-page-image" @click="previewDetail(pic)" /><text v-if="!item.description&&!details.length" class="muted">{{item.itemDetails}}</text></view><template v-else><view v-for="r in item.reviews" :key="r.id" class="review"><view class="row"><GameArt avatar :size="28" :type="r.avatar" :src="r.avatar?.startsWith('/')?r.avatar:''" /><text class="bold flex-1">{{r.nickname}}</text><text class="stars">{{'★'.repeat(r.stars)}}</text></view><text>{{r.content}}</text><text class="muted tiny">{{date(r.createdAt)}}</text></view><StateView :error="reviewError" :count="item.reviews.length" title="还没有评价" description="完成订单后，你也可以分享交易体验" @retry="moreReviews" /><button v-if="item.reviews.length<item.reviewTotal" class="ui-button load-more" :disabled="reviewsLoading" @click="moreReviews">{{reviewsLoading?'加载中…':'查看更多评价'}}</button></template></view><view class="notice"><AppIcon class="app-icon" name="shield" :size="18" /><text>下单前确认道具介绍、购买数量和游戏区服，实际收到道具后再确认收货。</text></view></view></template><template #footer><button class="ui-button favorite-btn" :disabled="!item||favoriting" @click="favorite"><AppIcon class="app-icon" name="star" :size="22" /><text>{{item?.favorited?'已收藏':'收藏'}}</text></button><button class="ui-button btn outline" :disabled="!item" @click="chatWith(item.ownerId,item.id)">联系{{item?.kind==='REQUEST'?'买家':'卖家'}}</button><button class="ui-button btn" :disabled="!item||busy" @click="purchase">{{item?.kind==='REQUEST'?'联系买家':'立即下单'}}</button></template></AppShell></template>
<script setup>
import {gameServerLabel} from '../../lib/playerTrade';import {computed,ref} from 'vue';import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import {request,go,money,date,images,imageUrl,requireLogin,chatWith,confirm,toast} from '../../lib/api';import {previewMedia} from '../../lib/media'
const id=ref(''),item=ref(null),loading=ref(true),error=ref(''),tab=ref('description'),busy=ref(false),favoriting=ref(false),reviewPage=ref(1),reviewsLoading=ref(false),reviewError=ref('');const pictures=computed(()=>images(item.value?.images));const specs=computed(()=>item.value?[{label:'游戏区服',value:gameServerLabel(item.value)},{label:'道具分类',value:item.value.itemCategory},{label:item.value.pricingMode==='UNIT'?(item.value.kind==='REQUEST'?'求购数量':'可购买数量'):'整批数量',value:(item.value.availableQuantity??item.value.quantity)+' 件'},{label:'道具介绍',value:item.value.itemDetails},...(item.value.pricingMode!=='UNIT'&&item.value.deliveryTerms?[{label:'交付约定',value:item.value.deliveryTerms}]:[])]:[])
const details=computed(()=>images(item.value?.detailImages));function previewDetail(pic){previewMedia(details.value,pic)}
let generation=0
onLoad(q=>{id.value=q.id});onShow(load);onUnload(()=>{generation++})
async function load(){
 const current=++generation;loading.value=true;error.value='';item.value=null;reviewsLoading.value=false;reviewError.value=''
 try{const result=await request('/boost/listings/'+id.value);if(current!==generation)return;item.value=result;reviewPage.value=1}
 catch(e){if(current===generation)error.value=e.message}
 finally{if(current===generation)loading.value=false}
}
async function moreReviews(){if(reviewsLoading.value||!item.value)return;const current=generation;reviewsLoading.value=true;reviewError.value='';try{const page=reviewPage.value+1,r=await request(`/boost/listings/${id.value}/reviews`,'GET',{page});if(current!==generation)return;item.value.reviews.push(...r.items);item.value.reviewTotal=r.total;reviewPage.value=page}catch(e){if(current===generation)reviewError.value=e.message}finally{if(current===generation)reviewsLoading.value=false}}
function preview(pic){previewMedia(pictures.value,pic)}
async function favorite(){if(!requireLogin()||!item.value||favoriting.value)return;const shown=item.value;favoriting.value=true;try{const result=await request(`/boost/listings/${id.value}/favorite`,'POST',{desired:!shown.favorited});if(item.value===shown)shown.favorited=result}catch(e){toast(e.message)}finally{favoriting.value=false}}
async function purchase(){if(!requireLogin()||!item.value||busy.value)return;if(item.value.kind==='SERVICE'){go('checkout/index',{id:id.value});return}const shown=item.value;busy.value=true;try{await chatWith(shown.ownerId,shown.id)}catch(e){if(e.code===409)await load();toast(e.message)}finally{busy.value=false}}
</script>
<style scoped>.detail-page-image{width:100%;display:block;margin:8px 0}.detail-swiper{height:285px}.detail-art{width:100%;height:100%}.detail-art-title{position:absolute;bottom:12px;left:16px;color:#fff;font-size:18px;font-weight:700;text-shadow:0 2px 5px #333}.detail-intro{border-radius:18px 18px 0 0;position:relative;margin-top:-12px}.detail-title{font-size:20px;font-weight:750;display:block;margin:10px 0}.assurances{gap:6px}.favorite-btn{font-size:10px;display:flex;flex-direction:column;align-items:center;min-width:38px}.description{white-space:pre-line;padding:20px 0;line-height:1.9;color:#5e606b}.review{padding:15px 0;border-bottom:1px solid #eee;display:flex;flex-direction:column;gap:8px;font-size:13px}.review .game-art{width:28px;height:28px}.detail-intro{padding:12px 16px;margin-bottom:0;border-radius:14px 14px 0 0}.detail-title{font-size:19px;margin:6px 0 9px}.detail-intro .price{font-size:27px}.assurances{flex-wrap:wrap;gap:7px}.spec-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;background:#f7f8fa;padding:13px;border-radius:10px}.spec-item{display:flex;flex-direction:column;gap:3px;font-size:13px;min-width:0}.description{padding:14px 0;line-height:1.75}.card .tabs{justify-content:space-around;padding:0}.detail-intro+.pad{background:#fff}.detail-intro+.pad>.card{padding:14px 0;margin-bottom:0;border-bottom:1px solid #f0f0f2;border-radius:0}</style>
